 67 | def get_rikishi_image_id(client: httpx.Client, profile_id: int) -> str | None:
 68 |     """Scrape the profile page to find the 270x474 image filename."""
 69 |     url = f"https://www.sumo.or.jp/EnSumoDataRikishi/profile/{profile_id}"
 70 |     resp = client.get(url)
 71 |     soup = BeautifulSoup(resp.text, "html.parser")
 72 |     # Look for the main profile image
 73 |     for img in soup.find_all("img"):
 74 |         src = img.get("src", "")
 75 |         if "270x474" in src:
 76 |             # Extract the filename like 20170096.jpg
 77 |             return src.split("/")[-1]
 78 |     return None
